<section class="patient-card mb-4"><div class="schedule-card-heading"><strong>Asistencia de pacientes a citas</strong><span><?= $escape($attendance['total']) ?> citas filtradas</span></div><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Atendidas</th><th>Inasistencias</th><th>Cancelaciones</th><th>Atención</th><th>Inasistencia</th><th>Cancelación</th></tr></thead><tbody><tr><td><?= $escape($attendance['atendidas']) ?></td><td><?= $escape($attendance['inasistencias']) ?></td><td><?= $escape($attendance['canceladas']) ?></td><td><?= $escape($percent((int)$attendance['atendidas'],(int)$attendance['total'])) ?></td><td><?= $escape($percent((int)$attendance['inasistencias'],(int)$attendance['total'])) ?></td><td><?= $escape($percent((int)$attendance['canceladas'],(int)$attendance['total'])) ?></td></tr></tbody></table></div></section>
<section class="patient-card mb-4"><div class="schedule-card-heading"><strong>Carga horaria por médico</strong><span>Periodo <?= $escape(($planningRange['from']??'').' – '.($planningRange['to']??'')) ?></span></div><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Médico</th><th>Horas semanales</th><th>Horas periodo</th><th>Ocupadas</th><th>Atendidas</th><th>Disponibles</th><th>Citas</th><th>Atendidas</th></tr></thead><tbody><?php foreach($workload as $row): ?><tr><td><?= $escape($row['medico_nombre']) ?></td><td><?= $escape(number_format((float)$row['horas_semanales_programadas'],2,',','.')) ?></td><td><?= $escape(number_format((float)$row['horas_programadas_periodo'],2,',','.')) ?></td><td><?= $escape(number_format((float)$row['horas_ocupadas'],2,',','.')) ?></td><td><?= $escape(number_format((float)$row['horas_atendidas'],2,',','.')) ?></td><td><?= $escape(number_format((float)$row['horas_disponibles'],2,',','.')) ?></td><td><?= $escape($row['citas_programadas']) ?></td><td><?= $escape($row['citas_atendidas']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="text-secondary small mb-0 mt-2">Programadas = unión de horarios activos, sin duplicar solapamientos; ocupadas = citas filtradas no canceladas; atendidas = estado atendida dentro del filtro; disponibles = franjas futuras libres según la agenda completa y sus bloqueos.</p></section>
